steps:
In an empty folder, create `notes.txt` with any text, then save `main.tf`:
```hcl
terraform {
  required_version = ">= 1.6"
  required_providers {
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.5"
    }
  }
}

resource "random_pet" "name" {
  length = 2
}

resource "local_file" "hello" {
  filename = "${path.module}/out/hello.txt"
  content  = "Hello, ${random_pet.name.id}\n"
}

data "local_file" "notes" {
  filename = "${path.module}/notes.txt"
}

output "notes_length" {
  value = length(data.local_file.notes.content)
}
```

Create the module and call it twice with `for_each`:
```hcl
# modules/greeting/main.tf
variable "name" {
  type = string
}

output "message" {
  value = "Hello, ${var.name}!"
}
```
```hcl
# main.tf (root module)
module "greeting" {
  source   = "./modules/greeting"
  for_each = toset(["dev", "prod"])
  name     = each.key
}

output "messages" {
  value = { for key, m in module.greeting : key => m.message }
}
```
